 <div class="curriculum-grid">${Object.entries(trackInfo).map(([id,t])=>`<div class="cert-card ${id}"><div class="cert-header"><span class="cert-label ${id}">${t.name.toUpperCase()}</span><span class="pill ${id==='ccna'?'':id==='ccnp'?'purple':'orange'}">${id==='ccna'?'ACTIVE PATH':'FUTURE PATH'}</span></div><h3>${t.title}</h3><p>${t.subtitle}</p><div class="progressline"><div style="width:${done(id)/count(id)*100}%"></div></div><div class="progress-label"><span>${done(id)} of ${count(id)} mapped</span><strong>${Math.round(done(id)/count(id)*100)}%</strong></div></div>`).join('')}</div>
