 recog.onresult=e=>{let t='';for(let i=e.resultIndex;i<e.results.length;i++)if(e.results[i].isFinal)t+=e.results[i][0].transcript+' ';s.teachText=(s.teachText+' '+t).trim();const ta=document.getElementById('teach-input');if(ta)ta.value=s.teachText;const c=document.getElementById('word-counter');if(c)c.textContent=counterText(s.teachText);};
 recog.onerror=e=>{toast(e.error==='not-allowed'||e.error==='service-not-allowed'?'The microphone is blocked on this page. Use “Type it” or another way, or open the downloaded file in Chrome to use “Say it”.':'Listening stopped ('+(e.error||'error')+'). You can type, or pick another way to show it.');};
 recog.onend=()=>{s.listening=false;if(page.view==='lesson')rerenderLesson();};
