function newRecheck(id){const l=lessons[id];if(!l)return null;const exam=Object.values(subjectExams).flatMap(e=>e.questions.filter(q=>q.topic===id));const pool=[...l.quiz,{q:l.lab.prompt,options:l.lab.options,answer:l.lab.answer,why:l.lab.explain},...exam];return{id,questions:shuffle(pool).slice(0,3).map(q=>({...q,choices:shuffle(q.options.map((label,index)=>({label,index})))})),answers:{},submitted:false,passed:false};}
function gradeRecheck(){const r=page.recheck;if(!r||r.submitted||Object.keys(r.answers).length<r.questions.length)return;r.submitted=true;r.passed=r.questions.every((q,i)=>r.answers[i]===q.answer);const same=pref('sameDay',false);if(r.passed){progress.mastered[r.id]=new Date().toISOString();delete progress.recheckDue[r.id];toast('Mastered! ★');}else{progress.recheckDue[r.id]=same?ymd(0):ymd(1);toast('Not yet. It will come back '+(same?'soon':'tomorrow')+'.');}save();renderSidebar();const y=scrollY;renderComeback();scrollTo(0,y);}
function renderComeback(){const r=page.recheck;
 if(r&&lessons[r.id]){const t=byId[r.id],n=Object.keys(r.answers).length;el.innerHTML=`<div class="section-top"><div><span class="eyebrow">COME-BACK CHECK</span><h1>${esc(t.title)}</h1><p>Three questions. No hints this time: this checks what your brain kept.</p></div><button class="secondary-btn" data-action="comeback">← All checks</button></div><div class="panel">${r.questions.map((q,i)=>`<div class="question-card"><div class="q-title"><span class="q-index">${i+1}.</span>${glossaryHTML(q.q)}</div><div class="options">${q.choices.map((o,j)=>{const sel=r.answers[i]===o.index,c=r.submitted&&o.index===q.answer?'correct':r.submitted&&sel?'incorrect':sel?'selected':'';return `<button class="option ${c}" data-rc-q="${i}" data-rc-a="${o.index}" ${r.submitted?'disabled':''}><span class="option-letter">${'ABCD'[j]}</span><span class="opt-txt">${glossaryHTML(o.label)}</span></button>`;}).join('')}</div>${r.submitted?`<div class="feedback ${r.answers[i]===q.answer?'good':'hint'}">${r.answers[i]===q.answer?'✓ Remembered.':'This one slipped.'} ${esc(q.why)}</div>`:''}</div>`).join('')}<div class="assessment-tools"><span class="small-print">${n}/${r.questions.length} answered</span>${r.submitted?'':`<button class="primary-btn small" data-action="rc-grade" ${n<r.questions.length?'disabled':''}>Check my answers</button>`}</div>${r.submitted?(r.passed?`<div class="celebrate"><h2>★ Mastered!</h2><p>You remembered <b>${esc(t.title)}</b> on a different day. That is how learning sticks.</p><button class="primary-btn small" data-action="comeback">Back to checks</button></div>`:`<div class="notice-card" style="margin-top:16px"><b>Not yet, and that is normal.</b> Read the explanations above. This check comes back ${pref('sameDay',false)?'soon':'tomorrow'}. Brains learn by coming back.<div class="btn-row" style="margin-top:12px"><button class="secondary-btn" data-topic="${t.id}">Review the lesson</button><button class="secondary-btn" data-action="comeback">Back to checks</button></div></div>`):''}</div>`;return;}
 page.recheck=null;const due=dueRechecks(),later=laterRechecks(),mastered=progress.completed.filter(isMastered);
 el.innerHTML=`<div class="section-top"><div><span class="eyebrow">MAKE IT STICK</span><h1>Come-back checks</h1><p>Learning sticks when you remember it on a different day. After you learn a lesson, it comes back here the next day as 3 quick questions with no hints. Get all 3 right and the lesson is <b>Mastered ★</b>.</p></div></div>
 <div class="panel"><h3>Ready now (${due.length})</h3>${due.length?due.map(id=>`<div class="subject-row"><div><b>${esc(byId[id].title)}</b><small>${esc(byId[id].domain)}</small></div><button class="primary-btn small" data-recheck="${id}">Start check →</button></div>`).join(''):`<p class="small-print">Nothing is ready right now. ${later.length?'Come back tomorrow!':'Learn a lesson first.'}</p>`}</div>
 ${later.length?`<div class="panel" style="margin-top:16px"><h3>Coming up</h3>${later.map(id=>`<div class="subject-row"><div><b>${esc(byId[id].title)}</b><small>Ready ${progress.recheckDue[id]===ymd(1)?'tomorrow':esc(progress.recheckDue[id])}</small></div></div>`).join('')}</div>`:''}
 <div class="panel" style="margin-top:16px"><h3>Mastered ★ (${mastered.length})</h3><p class="small-print">${mastered.length?mastered.map(id=>esc(byId[id].title)).join(' · '):'None yet. Your first one is coming.'}</p></div>
 <div class="review-warning" style="margin-top:16px">A subject exam opens when every lesson in that subject is Mastered ★.</div>`;}
function handleV6Click(b){const s=page.session;
 if(b.dataset.say!==undefined){const P=window.ATLAS_PREFS;if(!P)return true;if(P.speaking()){P.stop();return true;}if(!P.speak(lessonSpeech(b.dataset.say)))toast('This browser cannot read aloud.');return true;}
 if(b.dataset.mission){window.ATLAS_LAB?.open?.(b.dataset.mission);page.view='simulator';render();toast('When you finish, go to Overview → Continue learning to get back to your lesson.');return true;}
 if(page.view==='lesson'&&s){
  if(b.dataset.question!==undefined){const it=s.quiz[Number(b.dataset.question)];if(!it)return true;pickMC(it,Number(b.dataset.option));if(it.correct&&s.quiz.every(q=>q.correct))toast('Quiz finished. Nice work!');rerenderLesson();return true;}
  if(b.dataset.lab!==undefined){pickMC(s.lab,Number(b.dataset.lab));rerenderLesson();return true;}
  if(b.dataset.showMode){if(s.listening)stopListen();const ta=document.getElementById('teach-input');if(ta)s.teachText=ta.value;s.mode=b.dataset.showMode;if(!s.teachPassed)s.teachResult=null;rerenderLesson();return true;}
  if(b.dataset.pick!==undefined){const i=Number(b.dataset.pick);s.picked=s.picked.includes(i)?s.picked.filter(x=>x!==i):[...s.picked,i];rerenderLesson();return true;}
  if(b.dataset.adultTick!==undefined){const i=Number(b.dataset.adultTick);s.adultTicks=s.adultTicks.includes(i)?s.adultTicks.filter(x=>x!==i):[...s.adultTicks,i];rerenderLesson();return true;}
 }
 if(b.dataset.recheck){page.recheck=newRecheck(b.dataset.recheck);jump('comeback');return true;}
 if(b.dataset.rcQ!==undefined){const r=page.recheck;if(!r||r.submitted)return true;r.answers[Number(b.dataset.rcQ)]=Number(b.dataset.rcA);const y=scrollY;renderComeback();scrollTo(0,y);return true;}
 return false;}
function handleV6Action(action){const s=page.session,t=byId[page.topic],l=lessons[page.topic];
 if(action==='comeback'){page.recheck=null;jump('comeback');return true;}
 if(action==='rc-grade'){gradeRecheck();return true;}
 const lessonActions=['listen','stop-listen','check-pick','adult-confirm','check-teach','finish'];
 if(page.view!=='lesson'||!s||!t||!l)return lessonActions.includes(action);
 if(action==='listen'){startListen();return true;}
 if(action==='stop-listen'){stopListen();return true;}
 if(action==='check-teach'){const ta=document.getElementById('teach-input');if(ta)s.teachText=ta.value;progress.notes[t.id]=s.teachText;save();s.teachTries++;const r=gradeTeach(s.teachText,l,s.teachTries);s.teachPassed=r.ok;s.teachResult=r.msg;rerenderLesson();return true;}
 if(action==='check-pick'){const want=s.pickOpts.filter(o=>o.ok).length,right=s.picked.filter(i=>s.pickOpts[i].ok).length,wrong=s.picked.length-right;s.teachTries++;if(right===want&&!wrong){s.teachPassed=true;s.teachResult='✓ Yes! Those are exactly the ideas that belong to this lesson.';}else{s.teachResult=`You picked ${right} of ${want} right ideas${wrong?`, plus ${wrong} from a different lesson`:''}. Change your picks and check again.`;}rerenderLesson();return true;}
 if(action==='adult-confirm'){if(s.adultTicks.length<l.key.length){s.teachResult='Tick every idea you heard. If one is missing, ask a follow-up like “What happens when…?”';rerenderLesson();return true;}const P=window.ATLAS_PREFS;if(P&&!P.unlocked()){const v=document.getElementById('adult-pin')?.value||'';if(!P.unlock(v)){s.teachResult='That PIN is not right.';rerenderLesson();return true;}}s.teachPassed=true;s.teachResult='✓ A grown-up heard the learner explain every key idea.';rerenderLesson();return true;}
 if(action==='finish'){if(s.listening)stopListen();if(!progress.completed.includes(t.id)){if(!s.lab.correct||!s.quiz.every(q=>q.correct)||!s.teachPassed){toast('Finish Try it, the quiz and Show it first.');return true;}const same=pref('sameDay',false);progress.completed.push(t.id);progress.learnedAt[t.id]=new Date().toISOString();progress.recheckDue[t.id]=same?ymd(0):ymd(1);save();toast('You learned it! It comes back '+(same?'soon':'tomorrow')+' for a quick check.');}const following=topics[t.idx+1];if(following&&canAccess(following))openTopic(following.id);else jump('home');return true;}
 return false;}

function wordCount(s){return (s.trim().match(/\b[\w'-]+\b/g)||[]).length;}
function gradeTeach(text,l,tries=1){const min=Number(pref('minWords',12));const normalized=text.toLowerCase();const wc=wordCount(text);if(wc<min)return{ok:false,msg:`Keep going! Use at least ${min} words. You have ${wc}.`};
 const reEsc=x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');const has=term=>term.length<4?new RegExp('(?:^|\\W)'+reEsc(term)+'(?:$|\\W)','i').test(normalized):normalized.includes(term.toLowerCase());
 const missing=l.terms.filter(g=>!g.some(has));
 if(missing.length){if(tries<2)return{ok:false,msg:`Good start! ${missing.length===1?'One key idea is':missing.length+' key ideas are'} missing. Look at “Things you must know” and add more.`};
  const src=(l.paragraphs.join(' ')+' '+l.key.join(' ')+' '+l.teach).toLowerCase();const tips=missing.map(g=>g.find(x=>x.length>2&&new RegExp('\\b'+reEsc(x)+'\\b','i').test(src))||g[0]);
  return{ok:false,msg:`Getting closer! Try adding an idea about: ${tips.map(x=>'“'+x+'”').join(', ')}.`};}
 return{ok:true,msg:'✓ Your explanation has the key ideas. Read it once more to check it is true.'};}
// Study extensions: dictionary, term lookup, cumulative exams, review, resources.
const dictionary=Array.isArray(window.ATLAS_GLOSSARY)?window.ATLAS_GLOSSARY:[];
const termById=Object.fromEntries(dictionary.map(x=>[x.id,x]));
const termByLower=Object.fromEntries(dictionary.map(x=>[x.term.toLowerCase(),x]));
const glossaryPattern=new RegExp('\\b(?:'+dictionary.map(x=>x.term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).sort((a,b)=>b.length-a.length).join('|')+')\\b','gi');
const subjectExams=window.ATLAS_EXAMS||{};
const groupKey=t=>t.track+'||'+t.domain;
const groupsInOrder=[...new Set(topics.map(groupKey))];
const groupTopics=key=>topics.filter(t=>groupKey(t)===key);
const groupCanTest=key=>Boolean(subjectExams[key]&&groupTopics(key).every(t=>progress.completed.includes(t.id)&&progress.mastered[t.id]));
function pendingSubjectExam(){return groupsInOrder.find(key=>subjectExams[key]&&groupCanTest(key)&&!progress.subjectPassed.includes(key))||null;}
function previousGroupKey(t){const ix=topics.findIndex(x=>x.id===t.id);if(ix<=0)return null;const prior=topics[ix-1];return groupKey(prior)!==groupKey(t)?groupKey(prior):null;}
function glossaryHTML(value){const raw=String(value??'');if(!dictionary.length)return esc(raw);let out='',at=0;glossaryPattern.lastIndex=0;for(const m of raw.matchAll(glossaryPattern)){const entry=termByLower[m[0].toLowerCase()];if(!entry)continue;out+=esc(raw.slice(at,m.index));out+=`<span class="glossary-link" role="button" tabindex="0" data-glossary="${entry.id}" aria-label="Define ${esc(entry.term)}">${esc(m[0])}</span>`;at=m.index+m[0].length;}return out+esc(raw.slice(at));}
function openDefinition(id){const item=termById[id];if(!item)return;const m=document.getElementById('definition-modal');m.querySelector('.definition-term').textContent=item.term;m.querySelector('.definition-category').textContent=item.category+' · '+(item.level==='advanced'?'CCNP / CCIE':item.level==='ccna'?'CCNA':'Beginner');m.querySelector('.definition-meaning').innerHTML=glossaryHTML(item.definition);m.querySelector('.definition-example').innerHTML=glossaryHTML(item.example);const details=m.querySelector('.definition-deep-wrap');details.hidden=!item.detail;if(item.detail){m.querySelector('.definition-deep').innerHTML=glossaryHTML(item.detail);m.querySelector('.definition-pitfall').innerHTML=glossaryHTML(item.common_mistake||'');}m.querySelector('[data-definition-study]').dataset.definitionStudy=item.id;m.querySelector('[data-definition-dictionary]').dataset.definitionDictionary=item.id;m.classList.remove('hidden');m.querySelector('.definition-close').focus();}
function closeDefinition(){document.getElementById('definition-modal').classList.add('hidden');}
function renderToolkitHome(){const exam=pendingSubjectExam(),recent=progress.recapHistory.at(-1);return `<div class="section-top"><div><h2>Learning tools</h2><p>Revisit your weak spots, research a term, or prepare a real lab.</p></div></div><div class="tool-grid"><button class="tool-tile ready-tile" data-action="final"><span>🎓</span><b>Final CCNA exam</b><small>Three full 100-question, 120-minute practice exams that test every skill three ways, plus a PDF report for your AI tutor</small></button><button class="tool-tile" data-action="simulator"><span>⌘</span><b>Virtual Network Lab</b><small>Drag devices, wire cables, use real networking rules and guided CLI practice</small></button><button class="tool-tile" data-action="dictionary"><span>📚</span><b>Plain-English dictionary</b><small>${dictionary.length} networking terms · click-to-define inside lessons</small></button><button class="tool-tile" data-action="flashcards"><span>◈</span><b>Vocab flashcards</b><small>Flip, rate and review. Never a progression gate.</small></button><button class="tool-tile" data-action="match"><span>⇄</span><b>Definition Match</b><small>Drag words to definitions or tap to pair · six words per round</small></button><button class="tool-tile" data-action="recap"><span>▤</span><b>Recap quiz</b><small>Questions from topics you actually finished${recent?' · last '+recent.score+'%':''}</small></button><button class="tool-tile" data-action="resources"><span>⚒</span><b>Software & labs</b><small>Cisco Packet Tracer, Wireshark, CML, GNS3, official outlines</small></button><button class="tool-tile ${exam?'ready-tile':''}" data-action="subjects"><span>✺</span><b>Subject exams</b><small>${exam?'FOUNDATIONS EXAM READY — required before the next subject':'Cumulative tests required at subject boundaries'}</small></button></div>`;}
function renderDictionary(){const q=page.dictionaryQuery.toLowerCase(),category=page.dictionaryCategory,filtered=dictionary.filter(x=>(category==='all'||x.category===category)&&(`${x.term} ${x.definition} ${x.example}`).toLowerCase().includes(q));const shown=filtered.slice(0,page.dictionaryLimit);const cats=[...new Set(dictionary.map(x=>x.category))];el.innerHTML=`<div class="section-top"><div><span class="eyebrow">REFERENCE LIBRARY</span><h1>Network dictionary</h1><p>${dictionary.length} plain-English terms from the first Ethernet cable through CCIE infrastructure. This is a reference, not a gate.</p></div></div><div class="panel glossary-controls"><label>Search dictionary<input id="dictionary-query" value="${esc(page.dictionaryQuery)}" placeholder="Try MAC, router, OSPF, EVPN…" autocomplete="off"></label><label>Category<select id="dictionary-category"><option value="all">All categories</option>${cats.map(c=>`<option value="${esc(c)}" ${category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><span class="small-print">${filtered.length} results</span></div><div id="dictionary-results">${shown.length?`<div class="dictionary-grid">${shown.map(x=>`<button class="dictionary-entry" data-glossary="${x.id}"><span class="term-label">${esc(x.category)}</span><b>${esc(x.term)}</b><span>${esc(x.definition)}</span><em>Example: ${esc(x.example)}</em><small>Read details ↗</small></button>`).join('')}</div>`:'<div class="notice-card">Nothing matched. Try a shorter term.</div>'}${filtered.length>shown.length?`<button class="secondary-btn more-dictionary" data-action="dictionary-more">Show more (${filtered.length-shown.length} remaining)</button>`:''}</div>`;}
