const MATCH_ROUND_SIZE=6;
function matchDeck(){return dictionary.filter(d=>page.matchCategory==='all'||d.level===page.matchCategory);}
function newMatchRound(){
  const pool=matchDeck();
  // Prefer previously missed terms when requested, but always fill a complete round.
  const weak=shuffle(pool.filter(d=>progress.matchMissed.includes(d.id)));
  const regular=shuffle(pool.filter(d=>!progress.matchMissed.includes(d.id)));
  const selected=(page.matchWeakOnly?weak.concat(regular):shuffle(pool)).slice(0,MATCH_ROUND_SIZE);
  page.match={category:page.matchCategory,weakOnly:page.matchWeakOnly,ids:selected.map(d=>d.id),definitions:shuffle(selected.map(d=>d.id)),matched:[],selected:null,missIds:[],wrong:0,attempts:0,feedback:'Pick a term on the left, then choose the matching definition. You can also drag it onto the correct definition.',tone:'',recorded:false};
}
function matchData(){return page.match;}
function attemptMatch(termId,definitionId){
 const state=matchData();if(!state||state.recorded||!state.ids.includes(termId)||!state.definitions.includes(definitionId)||state.matched.includes(termId)||state.matched.includes(definitionId))return;
 const term=termById[termId];if(!term)return;
 state.attempts++;
 if(termId===definitionId){
   state.matched.push(termId);state.selected=null;state.feedback=`✓ ${term.term}: ${term.definition} Example: ${term.example}`;state.tone='good';
   if(!state.missIds.includes(termId)){progress.matchMissed=progress.matchMissed.filter(id=>id!==termId);}
   if(state.matched.length===state.ids.length){
     const firstTry=state.ids.length-state.missIds.length;
     const score=Math.round(firstTry/state.ids.length*100);
     progress.matchHistory.push({category:state.category,score,correct:firstTry,total:state.ids.length,misses:state.wrong,date:new Date().toISOString()});
     progress.matchHistory=progress.matchHistory.slice(-100);
     state.recorded=true;save();
   }
 }else{
   state.wrong++;
   if(!state.missIds.includes(termId))state.missIds.push(termId);
   if(!progress.matchMissed.includes(termId)){progress.matchMissed.push(termId);save();}
   state.selected=termId;state.feedback=`Not quite. “${term.term}” means something else. Try another definition. You can check the dictionary if you get stuck.`;state.tone='bad';
 }
 renderMatch();
 if(!state.recorded){const next=state.selected||state.ids.find(id=>!state.matched.includes(id));const button=[...el.querySelectorAll('[data-match-term]')].find(b=>b.dataset.matchTerm===next);button?.focus({preventScroll:true});}
}
function renderMatch(){
 if(!page.match||page.match.category!==page.matchCategory||page.match.weakOnly!==page.matchWeakOnly)newMatchRound();
 const s=page.match,completed=s.matched.length===s.ids.length,remaining=s.ids.length-s.matched.length;
 const history=progress.matchHistory.slice(-4).reverse();
 const firstTry=s.matched.length-s.missIds.filter(id=>s.matched.includes(id)).length;
 const cats=[['foundation','Beginner'],['ccna','CCNA'],['advanced','CCNP / CCIE'],['all','All 380 terms']];
 el.innerHTML=`<div class="match-hero"><span class="eyebrow">LEARN BY CONNECTING</span><h1>Definition <span style="color:var(--teal)">Match</span> ⇄</h1><p>Find the meaning of each networking word. Drag a word onto its definition, or tap a word and then a definition. Start with everyday networking language, then level up to CCNA and beyond.</p></div>
 <div class="filter-pills match-filters">${cats.map(([id,label])=>`<button data-match-category="${id}" class="${page.matchCategory===id?'active':''}">${label}</button>`).join('')}</div>
 <div class="match-banner"><div><b>How to play</b><br><span>Choose one word on the left. Match it with a meaning on the right. Green means correct; mistakes stay in your review list.</span></div><button class="secondary-btn" data-match-review="toggle">${page.matchWeakOnly?'✓ Reviewing weak words':'↻ Focus on missed words ('+matchDeck().filter(d=>progress.matchMissed.includes(d.id)).length+')'}</button></div>
 <div class="match-stats" aria-label="Round progress"><span><strong>${s.matched.length} / ${s.ids.length}</strong> pairs</span><span><strong>${s.wrong}</strong> wrong tries</span><span><strong>${remaining}</strong> left</span></div>
 <div class="match-board">
   <section class="match-col" aria-label="Words to match"><h2>1. WORDS</h2><p>Drag one to the right, or tap to select.</p><div class="match-stack">${s.ids.map(id=>{const d=termById[id],solved=s.matched.includes(id);return `<button type="button" class="match-term ${solved?'solved':''} ${s.selected===id?'selected':''}" data-match-term="${esc(id)}" draggable="${solved?'false':'true'}" aria-pressed="${s.selected===id}" ${solved?'disabled':''}><span>${esc(d.term)}</span><small>${solved?'✓ Matched':'Drag ⇢'}</small></button>`;}).join('')}</div></section>
   <section class="match-col" aria-label="Definitions to match"><h2>2. DEFINITIONS</h2><p>Drop the word on its meaning, or tap the matching card.</p><div class="match-stack">${s.definitions.map((id,i)=>{const d=termById[id],solved=s.matched.includes(id);return `<button type="button" class="match-definition ${solved?'solved':''} ${s.selected&&!solved?'ready':''}" data-match-definition="${esc(id)}" ${solved?'disabled':''}><span class="match-slot">${solved?'✓':i+1}</span><span>${esc(d.definition)}${solved?`<b>✓ ${esc(d.term)}</b>`:''}</span></button>`;}).join('')}</div></section>
 </div>
 <div class="match-feedback ${s.tone}" role="status" aria-live="polite">${esc(s.feedback)}</div>
 ${completed?`<div class="match-complete"><h2>🎉 Round complete!</h2><p>You matched all ${s.ids.length} words. <b>First-try accuracy: ${Math.round((s.ids.length-s.missIds.length)/s.ids.length*100)}%.</b> ${s.missIds.length?`${s.missIds.length} word(s) will stay on your missed-word practice list.`:'Perfect first tries — great work!'}</p><button class="primary-btn small" data-match-new="1">Play another round →</button></div>`:''}
 <div class="match-tools"><button class="secondary-btn" data-match-new="1">${completed?'Start new six-word round':'Shuffle / start new round'} ↻</button><button class="secondary-btn" data-action="dictionary">Open dictionary ↗</button></div>
 <p class="match-help">Use keyboard Tab + Enter to match, or drag with a mouse. On phones, tap a term and then its meaning (touch-drag also works). Practice scores never unlock lessons or subject exams.</p>
 ${history.length?`<div class="match-latest"><b>Recent rounds:</b> ${history.map(h=>esc(h.score)+'%').join(' · ')} first-try accuracy</div>`:''}`;
}
function renderFlashcards(){const x=page.flash,available=dictionary.filter(y=>x.category==='all'||y.level===x.category);let cards=available;if(x.missedOnly)cards=cards.filter(y=>progress.vocabRatings[y.id]==='again');if(x.knownOnly)cards=cards.filter(y=>progress.vocabRatings[y.id]==='known');if(x.index>=cards.length)x.index=0;const current=cards[x.index],known=available.filter(y=>progress.vocabRatings[y.id]==='known').length,missed=available.filter(y=>progress.vocabRatings[y.id]==='again').length;
 el.innerHTML=`<div class="section-top"><div><span class="eyebrow">ACTIVE RECALL</span><h1>Vocabulary flashcards</h1><p>Use the dictionary to understand the words, then test whether you remember them. Card ratings do <b>not</b> unlock lessons or subjects.</p></div></div><div class="filter-pills flash-filters">${[['all','Every term'],['foundation','Beginner'],['ccna','CCNA'],['advanced','CCNP / CCIE']].map(([k,v])=>`<button class="${x.category===k?'active':''}" data-flash-filter="${k}">${v}</button>`).join('')}</div><div class="flash-stat-row"><span>${available.length} terms in deck</span><span>✓ ${known} known</span><span>↻ ${missed} review again</span><button class="inline-link" data-action="flash-missed">${x.missedOnly?'Show all':'Only missed'}</button></div>${current?`<div class="flash-shell"><div class="flash-progress">Card ${x.index+1} / ${cards.length}</div><button data-action="flash-flip" class="flash-card" aria-label="Flip flashcard"><span class="content-label">${x.revealed?'EXPLANATION':'WHAT DOES THIS MEAN?'}</span><b>${x.revealed?esc(current.definition):esc(current.term)}</b>${x.revealed?`<small>Example: ${esc(current.example)}</small>`:'<small>Tap to reveal a plain-English definition</small>'}</button><div class="flash-actions">${x.revealed?`<button class="secondary-btn" data-action="flash-again">↻ Review again</button><button class="primary-btn small" data-action="flash-known">✓ I know it</button>`:`<button class="secondary-btn" data-action="flash-prev">← Previous</button><button class="secondary-btn" data-action="flash-flip">Reveal answer</button>`}<button class="secondary-btn" data-action="flash-next">Next →</button></div></div>`:'<div class="notice-card">No cards match your selection. Switch back to all terms, or mark some terms for review.</div>'}`;}
function newReviewSession(){let pool=[];for(const id of progress.completed){const l=lessons[id];if(!l)continue;pool.push(...l.quiz.map(q=>({...q,topic:id})));pool.push({...l.lab,q:l.lab.prompt,why:l.lab.explain,topic:id});}pool=shuffle(pool);const chosen=pool.slice(0,Math.min(10,pool.length));return{type:'recap',questions:chosen.map(q=>({...q,choices:shuffle(q.options.map((label,index)=>({label,index})))})),answers:{},submitted:false,score:0};}
function newSubjectSession(key){const cfg=subjectExams[key];if(!cfg)return null;const ids=groupTopics(key).map(t=>t.id),qs=[];for(const id of ids){const candidates=cfg.questions.filter(q=>q.topic===id);if(candidates.length)qs.push(shuffle(candidates)[0]);}const remaining=shuffle(cfg.questions.filter(q=>!qs.includes(q)));qs.push(...remaining.slice(0,Math.max(0,cfg.questionCount-qs.length)));return{type:'subject',key,questions:shuffle(qs).slice(0,cfg.questionCount).map(q=>({...q,choices:shuffle(q.options.map((label,index)=>({label,index})))})),answers:{},submitted:false,score:0};}
function renderQuizPanel(session,kind){if(!session||!session.questions.length)return '<div class="notice-card">Complete at least one authored concept first to generate recap questions.</div>';const complete=session.submitted,answers=Object.keys(session.answers).length,total=session.questions.length;return `<div class="quiz-run"><div class="quiz-meta"><b>${kind==='subject'?'Required subject test':'Optional retention gauge'}</b><span>${answers}/${total} answered</span></div>${session.questions.map((q,i)=>`<div class="question-card"><div class="q-title"><span class="q-index">${i+1}.</span> ${glossaryHTML(q.q)}</div><div class="options">${q.choices.map((o,j)=>`<button class="option ${complete&&o.index===q.answer?'correct':complete&&session.answers[i]===o.index?'incorrect':session.answers[i]===o.index?'selected':''}" data-recap-question="${i}" data-recap-answer="${o.index}" ${complete?'disabled':''}><span class="option-letter">${'ABCD'[j]}</span>${glossaryHTML(o.label)}</button>`).join('')}</div>${complete?`<div class="feedback ${session.answers[i]===q.answer?'good':'bad'}">${session.answers[i]===q.answer?'✓ Correct.':'✕ Review this concept.'} ${esc(q.why)}</div>`:''}</div>`).join('')}<div class="assessment-tools"><span class="small-print">${complete?`Score: ${session.score}% (${session.questions.filter((q,i)=>session.answers[i]===q.answer).length}/${total})`:total-answers+' answers remaining'}</span>${complete?`<button class="primary-btn small" data-action="${kind==='subject'?'subject-retry':'recap-retry'}">New set of questions ↻</button>`:`<button class="primary-btn small" data-action="${kind==='subject'?'subject-grade':'recap-grade'}" ${answers!==total?'disabled':''}>Submit all answers →</button>`}</div>${complete&&session.questions.some((q,i)=>session.answers[i]!==q.answer)?`<div class="notice-card" style="margin-top:17px"><b>Areas to revisit:</b> ${[...new Set(session.questions.filter((q,i)=>session.answers[i]!==q.answer).map(q=>byId[q.topic]?.title).filter(Boolean))].map(esc).join(' · ')}</div>`:''}${complete&&kind==='subject'?`<div class="feedback ${progress.subjectPassed.includes(session.key)?'good':'bad'}">${progress.subjectPassed.includes(session.key)?'Subject passed. The subject gate is now open.':'Score at least '+subjectExams[session.key].minimumPercent+'% to unlock the next subject. Review missed explanations before a new attempt.'}</div>`:''}</div>`;}
function renderRecap(){if(!page.review||page.review.type!=='recap')page.review=newReviewSession();const recent=progress.recapHistory.slice(-5).reverse();el.innerHTML=`<div class="section-top"><div><span class="eyebrow">RECALL & RETENTION</span><h1>Recap quiz</h1><p>Only topics you already mastered appear here. Retake as often as you like to measure retention; the result never unlocks a new subject.</p></div></div><div class="panel"><h2>Your completed-concept review</h2>${renderQuizPanel(page.review,'recap')}</div>${recent.length?`<div class="panel" style="margin-top:20px"><h3>Recent recap scores</h3><div class="history-row">${recent.map(x=>`<span>${x.score}% · ${new Date(x.date).toLocaleDateString()}</span>`).join('')}</div></div>`:''}`;}
function renderSubjects(){const keys=groupsInOrder.filter(k=>k.split('||')[0]==='ccna');el.innerHTML=`<div class="section-top"><div><span class="eyebrow">CUMULATIVE PROGRESSION GATES</span><h1>Subject exams</h1><p>A concept's short check proves that specific idea; a subject exam asks you to apply everything together. Passing a subject test is required before entering the next subject.</p></div></div><div class="panel">${keys.map(k=>{const ts=groupTopics(k),complete=ts.filter(t=>progress.completed.includes(t.id)).length,available=groupCanTest(k),passed=progress.subjectPassed.includes(k),cfg=subjectExams[k];return`<div class="subject-row"><div><b>${esc(ts[0].domain)}</b><small>${complete}/${ts.length} concepts finished · ${cfg?cfg.questionCount+' questions · '+cfg.minimumPercent+'% pass':'Assessment planned when lessons are authored'}</small></div><span class="topic-status ${passed?'complete':available?'available':'locked'}">${passed?'PASSED':available?'READY':'LOCKED'}</span>${cfg?`<button class="secondary-btn" data-subject="${esc(k)}" ${!available?'disabled':''}>${passed?'Retake for practice':'Take subject exam'} →</button>`:''}</div>`;}).join('')}</div><div class="review-warning" style="margin-top:20px">A passing score is a site access checkpoint, not an external certification, and the first release's automated exams cannot evaluate real physical-device skills. Later subjects will require deeper scenario and hands-on lab exams.</div>`;}
function renderSubjectExam(){const key=page.subject,ts=groupTopics(key);if(!ts.length){jump('subjects');return;}const cfg=subjectExams[key],ready=groupCanTest(key);if(!ready||!cfg){el.innerHTML=`<div class="gate-screen"><div class="gate-lock">⌁</div><h1>${esc(ts[0].domain)} subject exam is locked</h1><p>Learn every lesson in this subject and pass each come-back check (Mastered ★). Then the subject exam opens.</p><button class="primary-btn" data-action="continue">Return to current lesson</button></div>`;return;}if(!page.review||page.review.type!=='subject'||page.review.key!==key)page.review=newSubjectSession(key);el.innerHTML=`<div class="section-top"><div><span class="eyebrow">SUBJECT MASTERY EXAM</span><h1>${esc(cfg.title)}</h1><p>${cfg.questionCount} applied questions, one drawn from each concept in this subject. You must score ${cfg.minimumPercent}% or higher to cross into the next subject.</p></div><button class="secondary-btn" data-action="subjects">All subject exams</button></div><div class="panel">${renderQuizPanel(page.review,'subject')}</div>`;}
function gradeReview(){const s=page.review;if(!s||s.submitted||Object.keys(s.answers).length!==s.questions.length)return;s.submitted=true;const n=s.questions.filter((q,i)=>s.answers[i]===q.answer).length;s.score=Math.round(100*n/s.questions.length);if(s.type==='subject'){const cfg=subjectExams[s.key];progress.subjectHistory.push({key:s.key,score:s.score,date:new Date().toISOString()});progress.subjectHistory=progress.subjectHistory.slice(-100);if(s.score>=cfg.minimumPercent&&!progress.subjectPassed.includes(s.key))progress.subjectPassed.push(s.key);save();renderSubjectExam();toast(s.score>=cfg.minimumPercent?'Subject exam passed!':'Review your missed questions and try again.');}else{progress.recapHistory.push({score:s.score,date:new Date().toISOString(),count:s.questions.length});progress.recapHistory=progress.recapHistory.slice(-100);save();renderRecap();toast('Recap recorded: '+s.score+'%.');}}
