function downloadWorksheet(id){const w=worksheets.find(x=>x.id===id);if(!w)return;const body=['NETWORK ATLAS · '+w.name,'Requires: '+w.requires,'',w.goal,'','STEPS',...w.steps.map((s,i)=>(i+1)+'. '+s),'','PASS CRITERION',w.verify,'','Create and save your own Packet Tracer .pkt project where applicable. This downloadable file contains instructions only, not a .pkt simulation.'].join('\n');window.ATLAS_PREFS.saveFile(id+'-worksheet.txt',body,'text/plain').then(r=>{if(r==='saved'||r==='fallback')toast('Worksheet saved.');});}
function renderResources(){el.innerHTML=`<div class="section-top"><div><span class="eyebrow">TOOLS TO PRACTICE FOR REAL</span><h1>Software & download links</h1><p>Official sources for simulators, packet analysis, and exam objectives. Start with free Packet Tracer, then expand to more advanced emulation.</p></div></div><div class="resource-grid">${resources.map(x=>`<div class="panel resource-card"><span class="content-label">${esc(x.kind)}</span><h3>${esc(x.name)}</h3><p>${glossaryHTML(x.detail)}</p><div class="assessment-tools"><span class="small-print">${esc(x.stage)}</span><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer" class="secondary-btn">Official site ↗</a></div></div>`).join('')}</div><div class="section-top"><div><h2>Beginner lab worksheets</h2><p>Download the steps, build them in Packet Tracer or Wireshark, and save your own results. These are text instructions, not ready-made .pkt files.</p></div></div><div class="resource-grid">${worksheets.map(w=>`<div class="panel resource-card"><span class="content-label">${esc(w.requires)}</span><h3>${esc(w.name)}</h3><p>${glossaryHTML(w.goal)}</p><p class="small-print">Pass criterion: ${glossaryHTML(w.verify)}</p><button class="secondary-btn" data-download-lab="${w.id}">Download worksheet ↓</button></div>`).join('')}</div>`;}

function renderLocked(){const t=byId[page.topic];if(!t){jump('roadmap');return;}const missing=t.prereq.filter(p=>!progress.completed.includes(p)).map(p=>byId[p]);const reason=t.ready?(missing.length?`Master ${esc(missing[0].title)} first. You'll need to pass its scenario, quiz and teach-back.`:'This lesson is not currently accessible.'): 'This topic is mapped to the certification journey, but its complete learning content and assessment have not been authored yet.';
 el.innerHTML=`<div class="gate-screen"><div class="gate-lock">⌁</div><span class="eyebrow">PROGRESSION LOCK</span><h1>${esc(t.title)}</h1><p>${esc(t.desc)}</p><span class="pill neutral">${esc(trackInfo[t.track].name)} · ${esc(t.domain)}</span><div class="notice-card" style="margin:22px 0">${reason}</div><button class="primary-btn" data-action="continue">${nextId()?'Return to the current lesson':'Browse the roadmap'} →</button><button class="text-btn" data-action="back-roadmap">View the entire curriculum</button></div>`;
}
// Graph layout: group clusters (each with orbiting concept nodes), explicit prerequisite edges.
function buildGraphNodes(){const domains=[];const groups={};for(const t of topics){const key=t.track+'|'+t.domain;if(!groups[key]){groups[key]=[];domains.push({key,track:t.track,domain:t.domain});}groups[key].push(t);}const trackIndex={ccna:0,ccnp:1,ccie:2};const out=[];const centers={};for(const g of domains){const ix=domains.filter(z=>z.track===g.track).findIndex(z=>z.key===g.key),centerX=240+(ix%3)*465+trackIndex[g.track]*1550,centerY=230+Math.floor(ix/3)*510;centers[g.key]={x:centerX,y:centerY};const arr=groups[g.key];arr.forEach((t,j)=>{const outer=j>=8,order=outer?j-8:j,num=outer?arr.length-8:Math.min(arr.length,8);const rad=outer?151:91,ang=-Math.PI/2+2*Math.PI*order/num+(outer?.22:0);out.push({topic:t,x:centerX+Math.cos(ang)*rad,y:centerY+Math.sin(ang)*rad,g:g.key});});}return{nodes:out,centers,domains};}
const G=buildGraphNodes();
function renderGraph(){el.innerHTML=`<div class="section-top"><div><span class="eyebrow">YOUR CONNECTED SECOND BRAIN</span><h1 style="font-size:40px">Knowledge graph</h1><p>Every dot is a concept. Every line is a dependency. Explore the whole path without bypassing any mastery gate.</p></div></div><div class="concept-graph-shell" id="graph-shell"><canvas id="graph-canvas" aria-label="Interactive concept graph. Use curriculum view for an accessible list."></canvas><div class="graph-topbar">${[['ccna','CCNA'],['ccnp','CCNP'],['ccie','CCIE'],['all','All certifications']].map(([id,n])=>`<button data-graph-filter="${id}" class="${(page.graphFilter||'ccna')===id?'active':''}">${n}</button>`).join('')}</div><div class="graph-controls"><button data-action="zoom-in" aria-label="Zoom in">+</button><button data-action="zoom-out" aria-label="Zoom out">−</button><button data-action="zoom-fit" aria-label="Fit to screen">⌖</button></div><div class="graph-tip" id="graph-tip"></div></div><div class="graph-legend"><span class="legend-item ready">Currently unlocked</span><span class="legend-item complete">Mastered</span><span class="legend-item future">Future stages</span><span>Drag to move · Scroll to zoom · Click nodes to inspect</span></div><div class="notice-card" style="margin-top:20px"><b>How connections work:</b> Edges represent prerequisites and grouped study areas. The complete 158-node graph is mapped. Later lessons cannot be opened until the preceding topics are mastered and the lesson has been fully authored and assessed.</div>`;
 const c=document.getElementById('graph-canvas'),shell=document.getElementById('graph-shell'),tip=document.getElementById('graph-tip');let width=1,height=1,filter=page.graphFilter||'ccna';const cam={cx:0,cy:0,s:1};let moveStart=null,hover=null,rendered=[];const ctx=c.getContext('2d');let destroyed=false;
 function subset(){return G.nodes.filter(n=>filter==='all'||n.topic.track===filter);}
 function setFit(){const ns=subset();if(!ns.length)return;let minx=Math.min(...ns.map(n=>n.x))-225,maxx=Math.max(...ns.map(n=>n.x))+225,miny=Math.min(...ns.map(n=>n.y))-220,maxy=Math.max(...ns.map(n=>n.y))+190;cam.cx=(minx+maxx)/2;cam.cy=(miny+maxy)/2;cam.s=Math.max(.12,Math.min(2.1,Math.min(width/(maxx-minx),height/(maxy-miny))));draw();}
 function toS(x,y){return{x:(x-cam.cx)*cam.s+width/2,y:(y-cam.cy)*cam.s+height/2};}
 function toW(x,y){return{x:(x-width/2)/cam.s+cam.cx,y:(y-height/2)/cam.s+cam.cy};}
 function draw(){if(destroyed)return;ctx.clearRect(0,0,width,height);ctx.fillStyle='#0b1525';ctx.fillRect(0,0,width,height);const grd=ctx.createRadialGradient(width*.45,height*.44,0,width*.45,height*.44,width*.75);grd.addColorStop(0,'#142b40');grd.addColorStop(1,'#0b1525');ctx.fillStyle=grd;ctx.fillRect(0,0,width,height);
 ctx.fillStyle='#26374a';for(let x=-(cam.cx*cam.s-width/2)%38;x<width;x+=38)for(let y=-(cam.cy*cam.s-height/2)%38;y<height;y+=38){ctx.globalAlpha=.35;ctx.beginPath();ctx.arc(x,y,.8,0,7);ctx.fill();}ctx.globalAlpha=1;
 const ns=subset(),sel=new Set(ns.map(n=>n.topic.id));const pos=Object.fromEntries(ns.map(n=>[n.topic.id,n]));
 ctx.lineWidth=Math.max(.55,cam.s);for(const n of ns){const p=n.topic.prereq[0];if(!sel.has(p))continue;const a=toS(pos[p].x,pos[p].y),b=toS(n.x,n.y);ctx.strokeStyle=progress.completed.includes(p)&&progress.completed.includes(n.topic.id)?'#67f8cf9a':'#709bb04e';ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();}
 const domainList=G.domains.filter(d=>filter==='all'||d.track===filter);for(const d of domainList){const p=toS(G.centers[d.key].x,G.centers[d.key].y);ctx.fillStyle='#1b3146bb';ctx.beginPath();ctx.arc(p.x,p.y,Math.max(18,28*cam.s),0,7);ctx.fill();ctx.strokeStyle=d.track==='ccna'?'#367f73':d.track==='ccnp'?'#7257ac':'#97623e';ctx.lineWidth=1.2;ctx.stroke();ctx.font=`700 ${Math.max(9,Math.min(13,12*cam.s))}px DM Sans`;ctx.textAlign='center';ctx.fillStyle='#dce9f5';ctx.fillText(d.track.toUpperCase(),p.x,p.y+4);ctx.font=`700 ${Math.max(9,Math.min(12,12*cam.s))}px DM Sans`;ctx.fillStyle='#9bacc5';const words=d.domain.length>21?d.domain.slice(0,21)+'…':d.domain;ctx.fillText(words,p.x,p.y-Math.max(43,55*cam.s));}
 rendered=[];for(const n of ns){const p=toS(n.x,n.y),st=status(n.topic),r=Math.max(3,8.2*cam.s);if(p.x< -35||p.x>width+35||p.y< -35||p.y>height+35)continue;ctx.beginPath();ctx.arc(p.x,p.y,r+ (hover===n.topic.id?5:0),0,7);ctx.fillStyle=st==='complete'?'#a9ffee35':st==='available'?'#4de6bf3c':st==='future'?'#8d65d81d':'#5071921a';ctx.fill();ctx.beginPath();ctx.arc(p.x,p.y,r,0,7);ctx.fillStyle=st==='complete'?'#f0fff8':st==='available'?'#4de6bf':n.topic.track==='ccnp'?'#836bb5':n.topic.track==='ccie'?'#b78555':'#405e7b';ctx.fill();if(st==='available'){ctx.strokeStyle='#b2fff0';ctx.lineWidth=1.2;ctx.stroke();}if(cam.s>.69){ctx.font='11px DM Sans';ctx.textAlign='center';ctx.fillStyle=st==='available'?'#d4ffef':'#a5b7ca';ctx.fillText(n.topic.title.slice(0,25),p.x,p.y-14);}rendered.push({...n,sx:p.x,sy:p.y,r:Math.max(10,r+5)});}
 }
 function pointer(ev){const rect=c.getBoundingClientRect();return{x:ev.clientX-rect.left,y:ev.clientY-rect.top};}
 function hit(p){return [...rendered].reverse().find(n=>Math.hypot(n.sx-p.x,n.sy-p.y)<n.r);}
 function showTip(n,p){hover=n?.topic.id||null;if(n){tip.style.display='block';tip.innerHTML=`<b>${esc(n.topic.title)}</b><span>${esc(trackInfo[n.topic.track].name)} · ${status(n.topic)==='available'?'Unlocked':status(n.topic)==='complete'?'Mastered':'Locked'}</span>`;tip.style.left=Math.min(p.x+16,width-230)+'px';tip.style.top=Math.min(p.y+18,height-65)+'px';}else tip.style.display='none';draw();}
 const onDown=ev=>{moveStart={p:pointer(ev),cx:cam.cx,cy:cam.cy,moved:false};c.setPointerCapture(ev.pointerId);};
 const onMove=ev=>{const p=pointer(ev);if(moveStart){const dx=p.x-moveStart.p.x,dy=p.y-moveStart.p.y;if(Math.abs(dx)+Math.abs(dy)>5)moveStart.moved=true;cam.cx=moveStart.cx-dx/cam.s;cam.cy=moveStart.cy-dy/cam.s;showTip(null,p);}else showTip(hit(p),p);};
 const onUp=ev=>{if(!moveStart)return;const p=pointer(ev);if(!moveStart.moved){const n=hit(p);if(n)openTopic(n.topic.id);}moveStart=null;};
 const onWheel=ev=>{ev.preventDefault();const p=pointer(ev),before=toW(p.x,p.y);cam.s=Math.min(3.5,Math.max(.08,cam.s*(ev.deltaY>0?.89:1.12)));const after=toW(p.x,p.y);cam.cx+=before.x-after.x;cam.cy+=before.y-after.y;draw();};
 const onResize=()=>{const rect=c.getBoundingClientRect(),dpr=Math.min(2,window.devicePixelRatio||1);width=rect.width;height=rect.height;c.width=Math.round(width*dpr);c.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);setFit();};
 const resize=new ResizeObserver(onResize);resize.observe(c);c.addEventListener('pointerdown',onDown);c.addEventListener('pointermove',onMove);c.addEventListener('pointerup',onUp);c.addEventListener('pointerleave',()=>showTip(null,{x:0,y:0}));c.addEventListener('wheel',onWheel,{passive:false});
 page.graph={fit:setFit,zoom:factor=>{cam.s=Math.min(4,Math.max(.08,cam.s*factor));draw();},setFilter:id=>{filter=id;page.graphFilter=id;document.querySelectorAll('[data-graph-filter]').forEach(b=>b.classList.toggle('active',b.dataset.graphFilter===id));setFit();},dispose:()=>{destroyed=true;resize.disconnect();c.removeEventListener('pointerdown',onDown);c.removeEventListener('pointermove',onMove);c.removeEventListener('pointerup',onUp);c.removeEventListener('wheel',onWheel);}};
}
function continueLesson(){const pending=pendingSubjectExam();if(pending){page.subject=pending;page.review=null;jump('subjectExam');return;}const n=nextId();if(n)openTopic(n);else if(dueRechecks().length)jump('comeback');else if(progress.completed.length)openTopic(progress.completed.at(-1));else jump('roadmap');}
function saveBackup(){const backup={app:'Network Atlas',version:1,exportedAt:new Date().toISOString(),...progress};window.ATLAS_PREFS.saveFile('network-atlas-progress.json',JSON.stringify(backup,null,2),'application/json').then(r=>{if(r==='saved'||r==='fallback')toast('Progress backup saved.');});}
function importBackup(file){if(!file)return;file.text().then(txt=>{let raw;try{raw=JSON.parse(txt);if(!raw||raw.app!=='Network Atlas')throw Error();}catch(e){toast('That is not a Network Atlas backup.');return;}if(!(()=>{try{return window.self!==window.top}catch(e){return true}})()&&!window.confirm('Replace your saved progress with this backup?'))return;progress=cleanProgress(raw);save();page.view='home';render();toast('Backup imported.');}).catch(()=>toast('Unable to read that file.'));}
function searchOpen(){const m=document.getElementById('search-modal');m.classList.remove('hidden');const f=document.getElementById('search-input');f.value='';searchRender('');setTimeout(()=>f.focus(),30);}
function searchClose(){document.getElementById('search-modal').classList.add('hidden');}
function searchRender(q){const term=q.toLowerCase().trim();const arr=(term?topics.filter(t=>(t.title+' '+t.domain+' '+t.desc+' '+t.sub).toLowerCase().includes(term)):topics.filter(t=>status(t)==='available'||status(t)==='complete').slice(0,12)).slice(0,25);document.getElementById('search-results').innerHTML=arr.map(t=>`<button class="search-result" data-search-topic="${t.id}"><span><b>${esc(t.title)}</b><small>${esc(t.domain)} · ${esc(t.desc)}</small></span><em>${status(t)==='available'?'START':status(t)==='complete'?'MASTERED':'LOCKED'}</em></button>`).join('')||'<div class="notice-card">No matches. Try a protocol name such as OSPF, VLAN or DHCP.</div>';}
function handleAction(action){if(handleV6Action(action))return;const s=page.session,t=byId[page.topic],l=lessons[page.topic];if(action==='continue'){continueLesson();return;}if(action==='open-graph'){jump('graph');return;}if(action==='full-roadmap'||action==='back-roadmap'){page.track='all';jump('roadmap');return;}if(action==='zoom-in'){page.graph?.zoom(1.3);return;}if(action==='zoom-out'){page.graph?.zoom(1/1.3);return;}if(action==='zoom-fit'){page.graph?.fit();return;}if(['plan','ptbook','home','dictionary','flashcards','match','recap','subjects','resources','simulator','settings','final'].includes(action)){jump(action);return;}if(action==='dictionary-more'){page.dictionaryLimit+=48;renderDictionary();return;}if(action==='recap-grade'||action==='subject-grade'){gradeReview();return;}if(action==='recap-retry'){page.review=newReviewSession();renderRecap();return;}if(action==='subject-retry'){page.review=newSubjectSession(page.subject);renderSubjectExam();return;}if(action==='flash-missed'){page.flash.missedOnly=!page.flash.missedOnly;page.flash.knownOnly=false;page.flash.index=0;page.flash.revealed=false;renderFlashcards();return;}if(['flash-flip','flash-next','flash-prev','flash-known','flash-again'].includes(action)){const fx=page.flash,deck=dictionary.filter(y=>(fx.category==='all'||y.level===fx.category)&&(!fx.missedOnly||progress.vocabRatings[y.id]==='again'));const active=deck[fx.index];if(action==='flash-flip')fx.revealed=!fx.revealed;else if(action==='flash-next'){fx.index=(fx.index+1)%Math.max(1,deck.length);fx.revealed=false;}else if(action==='flash-prev'){fx.index=(fx.index-1+Math.max(1,deck.length))%Math.max(1,deck.length);fx.revealed=false;}else if(active){progress.vocabRatings[active.id]=action==='flash-known'?'known':'again';save();fx.index=(fx.index+1)%Math.max(1,deck.length);fx.revealed=false;}renderFlashcards();return;}if(!s||!t||!l)return;
}
el.addEventListener('click',ev=>{const term=ev.target.closest('[data-glossary]');if(term){ev.preventDefault();ev.stopPropagation();openDefinition(term.dataset.glossary);return;}const b=ev.target.closest('button');if(!b)return;if(handleV6Click(b))return;if(b.dataset.matchCategory){page.matchCategory=b.dataset.matchCategory;page.match=null;renderMatch();return;}if(b.dataset.matchReview){page.matchWeakOnly=!page.matchWeakOnly;page.match=null;renderMatch();return;}if(b.dataset.matchNew){newMatchRound();renderMatch();return;}if(b.dataset.matchTerm){if(matchSuppressClick)return;const s=matchData();if(!s||s.recorded||s.matched.includes(b.dataset.matchTerm))return;s.selected=b.dataset.matchTerm;s.feedback='Now choose the definition for “'+termById[s.selected].term+'”.';s.tone='';renderMatch();el.querySelectorAll('[data-match-term]').forEach(btn=>{if(btn.dataset.matchTerm===s.selected)btn.focus({preventScroll:true});});return;}if(b.dataset.matchDefinition){if(matchSuppressClick)return;const s=matchData();if(!s||s.recorded)return;if(!s.selected){s.feedback='Select a word on the left first.';s.tone='';renderMatch();return;}attemptMatch(s.selected,b.dataset.matchDefinition);return;}if(b.dataset.downloadLab){downloadWorksheet(b.dataset.downloadLab);return;}if(b.dataset.subject){page.subject=b.dataset.subject;page.review=null;jump('subjectExam');return;}if(b.dataset.flashFilter){page.flash.category=b.dataset.flashFilter;page.flash.index=0;page.flash.revealed=false;page.flash.missedOnly=false;renderFlashcards();return;}if(b.dataset.recapQuestion!==undefined){const s=page.review;if(!s||s.submitted)return;s.answers[Number(b.dataset.recapQuestion)]=Number(b.dataset.recapAnswer);s.type==='subject'?renderSubjectExam():renderRecap();return;}if(b.dataset.action){handleAction(b.dataset.action);return;}if(b.dataset.filter){page.track=b.dataset.filter;render();return;}if(b.dataset.graphFilter){page.graph?.setFilter(b.dataset.graphFilter);return;}if(b.dataset.domain){page.expanded[b.dataset.domain]=page.expanded[b.dataset.domain]===false;renderRoadmap();return;}if(b.dataset.topic){openTopic(b.dataset.topic);return;}if(b.dataset.question!==undefined){const s=page.session;if(!s||s.quizSubmitted)return;s.answers[Number(b.dataset.question)]=Number(b.dataset.option);renderLesson();document.getElementById('quiz-section').scrollIntoView({block:'start'});return;}if(b.dataset.lab!==undefined){const s=page.session,l=lessons[page.topic];if(!s||s.labPassed)return;s.labSelection=Number(b.dataset.lab);s.labPassed=s.labSelection===l.lab.answer;renderLesson();document.getElementById('lab-section').scrollIntoView({block:'start'});return;}});

/* Drag-and-drop on desktop; mobile touch drag, plus a reliable tap alternative. */
let matchDrag=null,matchPointer=null,matchGhost=null,matchSuppressClick=false;
function clearMatchDrag(){matchDrag=null;el.querySelectorAll('.drop-ready,.dragging').forEach(n=>n.classList.remove('drop-ready','dragging'));if(matchGhost){matchGhost.remove();matchGhost=null;}matchPointer=null;}
el.addEventListener('dragstart',ev=>{const b=ev.target.closest('[data-match-term]');if(!b||page.view!=='match'||b.disabled){ev.preventDefault();return;}matchDrag=b.dataset.matchTerm;ev.dataTransfer.setData('text/plain',matchDrag);ev.dataTransfer.effectAllowed='move';b.classList.add('dragging');});
el.addEventListener('dragover',ev=>{const b=ev.target.closest('[data-match-definition]');if(!b||!matchDrag||b.disabled)return;ev.preventDefault();ev.dataTransfer.dropEffect='move';el.querySelectorAll('.drop-ready').forEach(n=>n.classList.remove('drop-ready'));b.classList.add('drop-ready');});
el.addEventListener('drop',ev=>{const b=ev.target.closest('[data-match-definition]');if(!b||!matchDrag||b.disabled)return;ev.preventDefault();const id=matchDrag;clearMatchDrag();attemptMatch(id,b.dataset.matchDefinition);});
el.addEventListener('dragend',()=>clearMatchDrag());
el.addEventListener('pointerdown',ev=>{if(page.view!=='match'||ev.pointerType==='mouse')return;const b=ev.target.closest('[data-match-term]');if(!b||b.disabled)return;matchPointer={id:b.dataset.matchTerm,x:ev.clientX,y:ev.clientY,moved:false,pointerId:ev.pointerId};try{b.setPointerCapture(ev.pointerId);}catch(e){} });
el.addEventListener('pointermove',ev=>{if(!matchPointer||ev.pointerId!==matchPointer.pointerId)return;const p=matchPointer; if(!p.moved&&Math.hypot(ev.clientX-p.x,ev.clientY-p.y)<9)return;p.moved=true;ev.preventDefault();if(!matchGhost){matchGhost=document.createElement('div');matchGhost.className='match-drag-ghost';matchGhost.textContent=termById[p.id]?.term||'Word';document.body.append(matchGhost);}matchGhost.style.left=ev.clientX+'px';matchGhost.style.top=ev.clientY+'px';el.querySelectorAll('.drop-ready').forEach(n=>n.classList.remove('drop-ready'));const target=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-match-definition]');if(target&&!target.disabled)target.classList.add('drop-ready');});
el.addEventListener('pointerup',ev=>{if(!matchPointer||ev.pointerId!==matchPointer.pointerId)return;const p=matchPointer;const target=p.moved?document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-match-definition]'):null;clearMatchDrag();if(p.moved){matchSuppressClick=true;setTimeout(()=>matchSuppressClick=false,180);if(target&&!target.disabled)attemptMatch(p.id,target.dataset.matchDefinition);}});
el.addEventListener('pointercancel',ev=>{if(matchPointer&&ev.pointerId===matchPointer.pointerId)clearMatchDrag();});

el.addEventListener('input',ev=>{if(ev.target.id==='dictionary-query'){const caret=ev.target.selectionStart;page.dictionaryQuery=ev.target.value;page.dictionaryLimit=48;renderDictionary();const inp=document.getElementById('dictionary-query');inp.focus();inp.setSelectionRange(caret,caret);return;}if(ev.target.id==='teach-input'&&page.session){page.session.teachText=ev.target.value;const counter=document.getElementById('word-counter');if(counter)counter.textContent=counterText(ev.target.value);}});
el.addEventListener('change',ev=>{if(ev.target.id==='dictionary-category'){page.dictionaryCategory=ev.target.value;page.dictionaryLimit=48;renderDictionary();}});
document.querySelector('.side-nav').addEventListener('click',ev=>{const b=ev.target.closest('[data-view]');if(b)jump(b.dataset.view);});
document.getElementById('track-nav').addEventListener('click',ev=>{const b=ev.target.closest('[data-track]');if(!b)return;page.track=b.dataset.track;jump('roadmap');});
document.getElementById('export-btn').addEventListener('click',saveBackup);document.getElementById('import-btn').addEventListener('click',()=>document.getElementById('import-file').click());document.getElementById('import-file').addEventListener('change',ev=>{importBackup(ev.target.files[0]);ev.target.value='';});document.getElementById('search-trigger').addEventListener('click',searchOpen);document.getElementById('close-search').addEventListener('click',searchClose);document.getElementById('search-input').addEventListener('input',ev=>searchRender(ev.target.value));document.getElementById('search-results').addEventListener('click',ev=>{const b=ev.target.closest('[data-search-topic]');if(b){searchClose();openTopic(b.dataset.searchTopic);}});document.getElementById('search-modal').addEventListener('click',ev=>{if(ev.target.id==='search-modal')searchClose();});document.getElementById('mobile-menu').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){searchClose();closeDefinition();}if((ev.key==='Enter'||ev.key===' ')&&document.activeElement?.dataset.glossary){ev.preventDefault();openDefinition(document.activeElement.dataset.glossary);return;}if(ev.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){ev.preventDefault();searchOpen();}});
document.getElementById('definition-modal').addEventListener('click',ev=>{const sub=ev.target.closest('[data-glossary]');if(sub){ev.preventDefault();openDefinition(sub.dataset.glossary);return;}if(ev.target.id==='definition-modal'||ev.target.closest('.definition-close')){closeDefinition();return;}const practice=ev.target.closest('[data-definition-study]');if(practice){closeDefinition();page.flash.category='all';page.flash.missedOnly=false;page.flash.knownOnly=false;page.flash.index=Math.max(0,dictionary.findIndex(d=>d.id===practice.dataset.definitionStudy));page.flash.revealed=false;jump('flashcards');return;}const browse=ev.target.closest('[data-definition-dictionary]');if(browse){const d=termById[browse.dataset.definitionDictionary];if(d){closeDefinition();page.dictionaryQuery=d.term;page.dictionaryCategory='all';page.dictionaryLimit=48;jump('dictionary');}return;}});
window.ATLAS_APP={topics,lessons,byId,subjectExams,groupKey,get progress(){return progress},dueRechecks,pendingSubjectExam,jump};
if(!topics.length||!Object.keys(lessons).length){el.innerHTML='<div class="notice-card">Curriculum files could not be loaded. Open the complete site folder rather than index.html by itself.</div>';}else render();
